        seen = "depois de ver uma alternativa" if state.alternative_offered else "sem alternativa possível"
        return Decision("R07_negociacao", handoff=HandoffReason.NEGOCIACAO,
                        handoff_detail=f"Objeção ({objection.value}) {seen}.")  # fmt: skip

