"""Exporta as sessões do Claude Code deste projeto para ai-logs/, sem segredos.

Uso: uv run python scripts/export_ai_logs.py

O Claude Code guarda cada sessão em ~/.claude/projects/<caminho-do-projeto>/*.jsonl. O script
copia esses arquivos e, no caminho, substitui:
- o valor de cada variável do .env (chaves de API, workspace, chave do HMAC);
- qualquer coisa com cara de token (Anthropic, GitHub) ou id de workspace;
- o e-mail do autor (git config user.email) e o caminho da home (vira ~).

No fim, confere que nenhum dos valores substituídos sobrou nos arquivos exportados.
"""

from __future__ import annotations

import re
import subprocess
from pathlib import Path

REPO = Path(__file__).resolve().parents[1]
SESSIONS = Path.home() / ".claude" / "projects" / str(REPO).replace("/", "-")
OUT = REPO / "ai-logs" / "claude-code"

TOKEN_PATTERNS = {
    "ANTHROPIC_KEY": re.compile(r"sk-ant-[A-Za-z0-9_\-]{10,}"),
    "GITHUB_TOKEN": re.compile(r"\bgh[opsur]_[A-Za-z0-9]{10,}"),
    "WORKSPACE_ID": re.compile(r"\bwrkspc_[A-Za-z0-9]{6,}"),
}


def env_secrets() -> dict[str, str]:
    secrets = {}
    env = REPO / ".env"
    if env.exists():
        for line in env.read_text(encoding="utf-8").splitlines():
            if "=" in line and not line.lstrip().startswith("#"):
                name, value = line.split("=", 1)
                value = value.strip().strip("'\"")
                if len(value) >= 8 and not value.startswith("http"):
                    secrets[name.strip()] = value
    return secrets


def author_email() -> str | None:
    result = subprocess.run(
        ["git", "config", "user.email"], cwd=REPO, capture_output=True, text=True, check=False
    )
    return result.stdout.strip() or None


def scrub(text: str, literals: dict[str, str]) -> tuple[str, dict[str, int]]:
    counts: dict[str, int] = {}
    for label, value in literals.items():
        n = text.count(value)
        if n:
            text = text.replace(value, f"[REMOVIDO:{label}]")
            counts[label] = counts.get(label, 0) + n
    for label, pattern in TOKEN_PATTERNS.items():
        text, n = pattern.subn(f"[REMOVIDO:{label}]", text)
        if n:
            counts[label] = counts.get(label, 0) + n
    return text, counts


def main() -> None:
    literals = {f"env:{k}": v for k, v in env_secrets().items()}
    if email := author_email():
        literals["EMAIL_AUTOR"] = email
