git ls-files | grep -E "^\.env$|^var/" ; uv run -q python - <<'EOF'
import re, subprocess, pathlib
files = subprocess.run(["git", "ls-files"], capture_output=True, text=True).stdout.split()
secrets = {}
for line in pathlib.Path(".env").read_text().splitlines():
    if "=" in line and not line.startswith("#"):
        k, v = line.split("=", 1); v = v.strip()
        if len(v) >= 8: secrets[k] = v
email = subprocess.run(["git", "config", "user.email"], capture_output=True, text=True).stdout.strip()
secrets["EMAIL"] = email; secrets["EMAIL_USER"] = email.split("@")[0]
patterns = {"anthropic_key": re.compile(r"sk-ant-(?:api|admin)\d*-[A-Za-z0-9_\-]{20,}"),
            "github_token": re.compile(r"\bgh[opsur]_[A-Za-z0-9]{30,}"),
            "workspace_id": re.compile(r"\bwrkspc_[A-Za-z0-9]{10,}")}
hits = []
for f in files:
    try: text = pathlib.Path(f).read_text(encoding="utf-8")
    except (UnicodeDecodeError, FileNotFoundError): continue
    for label, value in secrets.items():
        if value in text: hits.append((f, label))
    for label, rx in patterns.items():
        if rx.search(text): hits.append((f, label))
print(f"{len(files)} arquivos versionados verificados; ocorrências: {hits or 'nenhuma'}")
EOF
